 internal static readonly ushort[] Quests;
 internal static void Register(int category,int slot,int mode,int achievement,uint[] items){Rules.Add(category+":"+slot,new Offline70TitleRuleFG157{Category=category,Slot=slot,Mode=mode,Achievement=achievement,Items=items});}
 internal static uint Reward(ushort q){int[] row=Row(q);return row==null?0u:(uint)row[1];}
 internal static int AwardCategoryFG173(ushort q){int[] row=Row(q);if(row==null)throw new InvalidDataException("Title award quest");return row[2];}
