 internal static bool OriginalAdjustment(ushort q){return q==4303||q==1028||q==2||q==4423;}
 static int[] Row(ushort q){int[] row;return AwardFG205.TryGetValue((int)q,out row)?row:null;}
 internal static void CheckProfile(Offline70QuestDefinitionFG q){if(!q.TitleRewardFG157)return;if(Row(q.Id)==null||q.Grade!="[achievement]"||q.Rewards.Length!=2||q.Rewards[0]!=Reward(q.Id)||q.Rewards[1]!=1||q.Selection.Length!=0||q.Repeatable||q.JobChange)throw new InvalidDataException("Original title quest profile");}
 static void Slot(int category,int slot){if(category<0||category>3||slot<0||slot>=Capacity[category]||!Rules.ContainsKey(category+":"+slot)||Rules[category+":"+slot].Mode<0)throw new InvalidDataException("Title book original slot");}
 internal static Offline70TitleSlotFG157 Find(Offline70EconomyState s,int category,int slot){foreach(Offline70TitleSlotFG157 b in s.TitleBookFG157)if(b.Category==category&&b.Slot==slot)return b;return null;}
 static void Item(Offline70EconomyEntry e){if(e==null)throw new InvalidDataException("Missing title");Offline70EconomyItemDefinition d=Offline70Economy.Definition(e.ItemId);if(d.Kind!=4||d.EquipSlot!=11||e.Quantity!=1||e.Ability!=0||e.ExpiresUnix!=0||e.Durability>d.MaxDurability||e.Upgrade>31||e.ResealCount>7||e.EquipmentSeed<-1||e.CreatureKey!=0||e.CreatureExperience!=0||e.CreatureLevel!=0||e.CreatureSatiety!=0||e.CreatureFeedUtcTicks!=0||!String.IsNullOrEmpty(e.CreatureName))throw new InvalidDataException("Title ownership properties");}
 internal static void Validate(Offline70EconomyState s){if(s.TitleBookFG157==null||s.TitleBookFG157.Count>330||s.TitleAwardsFG157==null||s.TitleAwardsFG157.Count>Quests.Length)throw new InvalidDataException("Title book bounds");HashSet<string> slots=new HashSet<string>();foreach(Offline70TitleSlotFG157 b in s.TitleBookFG157){if(b==null)throw new InvalidDataException("Null title book row");Slot(b.Category,b.Slot);Item(b.Item);if(b.Item.List!=0||b.Item.Slot!=3||!slots.Add(b.Category+":"+b.Slot))throw new InvalidDataException("Title book duplicate position");}HashSet<ushort> awards=new HashSet<ushort>();foreach(ushort q in s.TitleAwardsFG157)if(Row(q)==null||!awards.Add(q)||!s.CompletedQuests.Contains(q))throw new InvalidDataException("Title award ledger");}
 internal static string Fingerprint(Offline70EconomyState s){using(MemoryStream m=new MemoryStream()){new XmlSerializer(typeof(List<Offline70TitleSlotFG157>)).Serialize(m,s.TitleBookFG157);foreach(ushort q in s.TitleAwardsFG157){byte[] b=BitConverter.GetBytes(q);m.Write(b,0,b.Length);}using(SHA256 h=SHA256.Create()){return Convert.ToBase64String(h.ComputeHash(m.ToArray()));}}}
 static bool Owned(Offline70EconomyState s,uint item){foreach(Offline70EconomyEntry e in s.Inventory)if(e.ItemId==item)return true;foreach(Offline70TitleSlotFG157 b in s.TitleBookFG157)if(b.Item.ItemId==item)return true;return false;}
 internal static void Award(Offline70EconomyState s,ushort q){if(Row(q)==null||!s.CompletedQuests.Contains(q))throw new InvalidDataException("Title original completion");if(s.TitleAwardsFG157.Contains(q))return;uint id=Reward(q);Offline70Economy.Definition(id);if(!Owned(s,id)){if(Find(s,AwardCategoryFG173(q),AwardSlotFG173(q))!=null)throw new InvalidDataException("Title reward slot occupied; withdraw displaced title first");s.TitleBookFG157.Add(new Offline70TitleSlotFG157{Category=AwardCategoryFG173(q),Slot=AwardSlotFG173(q),Item=new Offline70EconomyEntry{List=0,Slot=3,ItemId=id,Quantity=1,EquipmentSeed=0,Sealed=true}});}s.TitleAwardsFG157.Add(q);}
 internal static Offline70TitleRequestFG157 Parse(ushort op,byte[] encrypted,byte[] keys){if(op!=420&&op!=421||encrypted==null||encrypted.Length!=(op==420?20:32))throw new InvalidDataException("Title request length");byte[] p=Offline70RoleProtocol.BatchCryptFG(encrypted,keys,op%14,false);for(int i=20;i<p.Length;i++)if(p[i]!=0)throw new InvalidDataException("Title request padding");Offline70TitleRequestFG157 r=new Offline70TitleRequestFG157{InventoryType=BitConverter.ToInt32(p,0),InventorySlot=BitConverter.ToInt32(p,4),Item=BitConverter.ToUInt32(p,8),Category=BitConverter.ToInt32(p,12),BookSlot=BitConverter.ToInt32(p,16)};Slot(r.Category,r.BookSlot);if(r.InventoryType!=0&&r.InventoryType!=3&&r.InventoryType!=17||r.InventoryType==0&&(r.InventorySlot<3||r.InventorySlot>40)||r.InventoryType!=0&&r.InventorySlot!=11||r.Item==0)throw new InvalidDataException("Title request routing");return r;}
 static void PutFits(Offline70EconomyEntry item,Offline70TitleRequestFG157 r){Offline70TitleRuleFG157 rule=Rules[r.Category+":"+r.BookSlot];if(rule.Mode<0)throw new InvalidDataException("Inactive title book slot");if(r.Category==3){if(item.Sealed)throw new InvalidDataException("Event book requires original unsealed title");return;}foreach(uint id in rule.Items)if(item.ItemId==id)return;throw new InvalidDataException("Title does not match original book slot");}
 internal static Offline70EconomyState Move(string path,string receipt,ushort op,Offline70TitleRequestFG157 r,out bool duplicate){if(op!=420&&op!=421)throw new InvalidDataException("Title operation");return Offline70Economy.Apply(path,receipt,"title-book",op+":"+r.InventoryType+":"+r.InventorySlot+":"+r.Item+":"+r.Category+":"+r.BookSlot,delegate(Offline70EconomyState s){if(s.Level<10||r.Category==2&&s.Level<70)throw new InvalidDataException("Title book level admission");byte list=(byte)(r.InventoryType==0?0:3);ushort slot=(ushort)r.InventorySlot;Offline70EconomyEntry worn=Offline70Economy.Find(s,list,slot);Offline70TitleSlotFG157 book=Find(s,r.Category,r.BookSlot);if(op==420){if(worn==null||worn.ItemId!=r.Item)throw new InvalidDataException("Title put ownership");Item(worn);PutFits(worn,r);if(list==0&&book!=null)throw new InvalidDataException("Title bag put target occupied; native E2B380 does not exchange different items");}else{if(book==null||book.Item.ItemId!=r.Item)throw new InvalidDataException("Title get ownership");if(list==0&&worn!=null)throw new InvalidDataException("Title withdrawal target occupied");if(worn!=null)Item(worn);}
 if(book!=null&&list==3){Offline70EconomyItemDefinition d=Offline70Economy.Definition(book.Item.ItemId);uint now=(uint)(DateTime.UtcNow-new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc)).TotalSeconds;if(s.Level+(Offline70FeedbackFG129.Active(s,22,now)?5:0)<d.MinimumLevel||(d.Job!=255&&d.Job!=s.Job)||(d.JobMask!=0&&(d.JobMask&(1u<<s.Job))==0))throw new InvalidDataException("Title equipped eligibility");}if(worn!=null)s.Inventory.Remove(worn);if(book!=null)s.TitleBookFG157.Remove(book);if(book!=null){Offline70EconomyEntry next=book.Item;if(list==3)next.Sealed=false;next.List=list;next.Slot=slot;s.Inventory.Add(next);}if(worn!=null){worn.List=0;worn.Slot=3;s.TitleBookFG157.Add(new Offline70TitleSlotFG157{Category=r.Category,Slot=r.BookSlot,Item=worn});}
 },out duplicate);}
 internal static byte[] ListBody(Offline70EconomyState s,int category){using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write((byte)0);w.Write((ushort)0);w.Write(category);List<Offline70TitleSlotFG157> rows=s.TitleBookFG157.FindAll(delegate(Offline70TitleSlotFG157 b){return b.Category==category;});rows.Sort(delegate(Offline70TitleSlotFG157 a,Offline70TitleSlotFG157 b){return a.Slot.CompareTo(b.Slot);});w.Write(rows.Count);foreach(Offline70TitleSlotFG157 b in rows){Offline70EconomyEntry e=b.Item;w.Write((ushort)b.Slot);w.Write(e.ItemId);w.Write(Offline70EconomyProtocol.ItemData(e));w.Write(Offline70ItemResealFG102.Attribute(e));w.Write(e.Durability);w.Write((byte)(e.Sealed?1:0));w.Write((uint)0);w.Write((byte)0);w.Write((ushort)0);}return m.ToArray();}}
 internal static byte[] StateBody(Offline70EconomyState s){using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write(s.TitleAwardsFG157.Count);foreach(ushort q in s.TitleAwardsFG157){w.Write(AchievementFG173(q));w.Write((ushort)0);w.Write((ushort)0);w.Write((ushort)0);}return m.ToArray();}}
 internal static byte[] AwardBody(ushort q){if(Row(q)==null)throw new InvalidDataException("Title reward notification");using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write(AchievementFG173(q));w.Write((uint)AwardCategoryFG173(q));w.Write((uint)AwardSlotFG173(q));w.Write(Reward(q));w.Write((ushort)0);return m.ToArray();}}
 internal static byte[] Reply(ushort op,Offline70TitleRequestFG157 r,bool success,byte[] keys){using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write((byte)(success?1:0));if(success){w.Write(r.InventoryType);w.Write(r.InventorySlot);w.Write(r.Category);w.Write(r.BookSlot);}else{w.Write((byte)19);w.Write(r==null?0:r.InventoryType);w.Write(r==null?0:r.Category);}return Offline70RoleProtocol.BatchPacketFG(1,op,m.ToArray(),keys,false);}}
}
partial class Offline70BatchServiceFG {
 readonly Dictionary<string,string> titleRequestsFG157=new Dictionary<string,string>();readonly Dictionary<string,byte[]> titleRepliesFG157=new Dictionary<string,byte[]>();
 void TitleListsFG157(){for(int category=0;category<4;category++)Send("title-book367-"+category,Offline70RoleProtocol.BatchPacketFG(0,367,Offline70TitleBookFG157.ListBody(assets,category),keys,false));Send("title-achievements368",Offline70RoleProtocol.BatchPacketFG(0,368,Offline70TitleBookFG157.StateBody(assets),keys,false));}
 // FG381: n_quest/title/titlebook_1_general30.qst grants 26628 DNF时代先锋 the moment the
 // character reaches Lv70 ([custom quest], no NPC hand-in). The hook covers the live level-up
 // and, with a fixed receipt, the world entry of characters that hit 70 before it existed.
 void Lv70TitleHealFG381(string receipt,byte level){
  if(assets==null||level<70||assets.CompletedQuests.Contains(6531)||assets.TitleAwardsFG157.Contains(6531))return;
  Offline70EconomyState beforeTitle=assets;bool duplicate;
  try{assets=Offline70Economy.Apply(economyPath,receipt,"lv70-title","6531:26628",delegate(Offline70EconomyState s){
   if(!s.CompletedQuests.Contains(6531))s.CompletedQuests.Add(6531);
   Offline70TitleBookFG157.Award(s,6531);
  },out duplicate);TitleChangedFG157(beforeTitle);Note("LV70_TITLE_COMMITTED quest=6531 item=26628 level="+level+" duplicate="+duplicate);}
  catch(InvalidDataException e){Note("LV70_TITLE_REJECTED reason="+e.Message);}
 }
 void RecoverTitlesFG157(){foreach(ushort q in Offline70TitleBookFG157.Quests){if(!Offline70TitleBookFG157.OriginalAdjustment(q)||!progress.Completed.Contains(q)||!assets.CompletedQuests.Contains(q)||assets.TitleAwardsFG157.Contains(q))continue;try{bool duplicate;ushort id=q;assets=Offline70Economy.Apply(economyPath,"title-adjust-"+q,"title-adjust",q+":"+Offline70TitleBookFG157.Reward(q),delegate(Offline70EconomyState s){Offline70TitleBookFG157.Award(s,id);},out duplicate);Note("TITLE_ADJUST_COMMITTED quest="+q+" oldInventoryPreserved=True duplicate="+duplicate);}catch(InvalidDataException e){Note("TITLE_ADJUST_REJECTED quest="+q+" reason="+e.Message);}}}
 void TitleChangedFG157(Offline70EconomyState before){foreach(ushort q in assets.TitleAwardsFG157)if(!before.TitleAwardsFG157.Contains(q)){Offline70TitleSlotFG157 added=Offline70TitleBookFG157.Find(assets,Offline70TitleBookFG157.AwardCategoryFG173(q),Offline70TitleBookFG157.AwardSlotFG173(q));if(added!=null&&added.Item.ItemId==Offline70TitleBookFG157.Reward(q))Send("title-award369",Offline70RoleProtocol.BatchPacketFG(0,369,Offline70TitleBookFG157.AwardBody(q),keys,false));}if(before.TitleAwardsFG157.Count!=assets.TitleAwardsFG157.Count)Send("title-achievements368",Offline70RoleProtocol.BatchPacketFG(0,368,Offline70TitleBookFG157.StateBody(assets),keys,false));}
 void TitleMoveFG157(ushort op,byte[] body,ushort sequence){string id=op+":"+sequence,fingerprint=Convert.ToBase64String(body),old;if(titleRequestsFG157.TryGetValue(id,out old)){if(old!=fingerprint){Offline70TitleRequestFG157 conflict=null;try{conflict=Offline70TitleBookFG157.Parse(op,body,keys);}catch(InvalidDataException){}Note("TITLE_SEQUENCE_CONFLICT op="+op+" noMutation=True");Send("title-conflict"+op,Offline70TitleBookFG157.Reply(op,conflict,false,keys));return;}Send("title-repeat"+op,titleRepliesFG157[id]);return;}Offline70TitleRequestFG157 r=null;bool success=false;try{if(dungeon.Active||playerDeadFG117)throw new InvalidDataException("Title book requires live town actor");r=Offline70TitleBookFG157.Parse(op,body,keys);Sync();bool duplicate;assets=Offline70TitleBookFG157.Move(economyPath,session+"-title-"+op+"-"+sequence,op,r,out duplicate);success=true;Note("TITLE_MOVE_COMMITTED op="+op+" inventory="+r.InventoryType+":"+r.InventorySlot+" category="+r.Category+" bookSlot="+r.BookSlot+" item="+r.Item+" duplicate="+duplicate);}catch(InvalidDataException e){Note("TITLE_MOVE_REJECTED "+e.Message);}byte[] reply=Offline70TitleBookFG157.Reply(op,r,success,keys);titleRequestsFG157.Add(id,fingerprint);titleRepliesFG157.Add(id,reply);Send(success?"title-moved"+op:"title-failed"+op,reply);/* Live report 2026-10-26 (triage #10): a committed wear/unwear left the client's worn rows and attribute block stale, so the head title and panel stats never appeared. Refresh both - the same thing an op19 worn-list move already does; this handler is town-only, so the appearance-deferral guard does not apply. */if(success){Sync();Appearance();Send("title-attributes",AdditionReplyFG129());}Note("TITLE_REFRESH_AFTER_MOVE op="+op+" success="+success);}
}
